import { readFile } from "node:fs/promises";
import assert from "node:assert/strict";

const wasm = await readFile(new URL("./ui_framework.wasm", import.meta.url));
const { instance } = await WebAssembly.instantiate(wasm, {});
const e = instance.exports;
const mem = new Uint8Array(e.memory.buffer);
const view = new DataView(e.memory.buffer);

function writeAscii(ptr, value) {
  for (let i = 0; i < value.length; i += 1) mem[ptr + i] = value.charCodeAt(i);
}

function readAscii(ptr, len) {
  return String.fromCharCode(...mem.slice(ptr, ptr + len));
}

function assertSameBytes(leftBase, leftEnd, rightBase, rightEnd) {
  const leftLen = leftEnd - leftBase;
  const rightLen = rightEnd - rightBase;
  assert.equal(leftLen, rightLen);
  assert.deepEqual([...mem.slice(leftBase, leftEnd)], [...mem.slice(rightBase, rightEnd)]);
}

let parityScratch = 760000;
function assertGalleryConstructorBytes(kind, id, buildConstructor) {
  const galleryBase = parityScratch;
  const ctorBase = parityScratch + 280;
  parityScratch += 560;
  const galleryEnd = e.er_ui_gallery_preview_build_basic(kind, galleryBase, 256, id);
  const ctorEnd = buildConstructor(ctorBase);
  assert.equal(e.er_ui_validate_deep(galleryBase, galleryEnd - galleryBase), 1);
  assert.equal(e.er_ui_validate_deep(ctorBase, ctorEnd - ctorBase), 1);
  assertSameBytes(galleryBase, galleryEnd, ctorBase, ctorEnd);
}

function fnv1aHitId(namespace, role, key) {
  let hash = 0x811c9dc5;
  const update = (byte) => {
    hash ^= byte;
    hash = Math.imul(hash, 16777619) >>> 0;
  };
  for (const part of ["edgerun:ui-hit:v1", namespace, "\0", role, "\0", key]) {
    for (let i = 0; i < part.length; i += 1) update(part.charCodeAt(i));
  }
  return hash === 0 ? 1 : hash;
}

